import subprocess, os, struct

header = b'masscan/1.1\r\n\x1a'

# Let's test what happens if we write header + 1 byte ... 100 bytes
for l in range(1, 40):
    with open('test.scan', 'wb') as f:
        f.write(header + bytes(range(l)))
    res = subprocess.run(['./executable', '--readscan', 'test.scan'], capture_output=True, text=True)
    if 'corrupt' in res.stderr.lower() or 'error' in res.stderr.lower() or 'fail' in res.stderr.lower():
        print(f'len={l}: stderr={repr(res.stderr)}')

if os.path.exists('test.scan'):
    os.remove('test.scan')
""}

