{"command":"python3 -c "
import subprocess, os, struct

header = b'masscan/1.1\r\n\x1a'

for rectype in range(20):
    for plen in [12, 13, 14, 16, 20]:
        for endian in ['>', '<']:
            payload = struct.pack(endian + 'I', 1600000000) + struct.pack(endian + 'I', 0x01020304) + struct.pack(endian + 'H', 80) + bytes([1, 64])
            if len(payload) < plen:
                payload += b'\x00' * (plen - len(payload))
            rec_hdr = bytes([rectype]) + struct.pack(endian + 'H', len(payload))
            data = header + rec_hdr + payload
            with open('test.scan', 'wb') as f:
                f.write(data)
            subprocess.run(['./executable', '-oL', 'out.txt', '--readscan', 'test.scan'], capture_output=True, text=True)
            if os.path.exists('out.txt'):
                with open('out.txt') as outf:
                    txt = outf.read()
                os.remove('out.txt')
                if txt:
                    print(f'FOUND RECORD! rectype={rectype}, plen={plen}, endian={endian}: {repr(txt)}')

if os.path.exists('test.scan'):
    os.remove('test.scan')
""}

