#include <string.h>
#include <ctype.h>
#include <arpa/inet.h>

void rangelist_init(struct RangeList *rl) {
    rl->list = NULL;
    rl->count = 0;
    rl->max = 0;
}

void rangelist_free(struct RangeList *rl) {
    if (rl->list) {
        free(rl->list);
        rl->list = NULL;
    }
    rl->count = 0;
    rl->max = 0;
}

static void rangelist_push(struct RangeList *rl, const struct Range *r) {
    if (rl->count >= rl->max) {
        rl->max = rl->max ? rl->max * 2 : 16;
        rl->list = realloc(rl->list, rl->max * sizeof(struct Range));
    }
    rl->list[rl->count++] = *r;
}

void rangelist_add(struct RangeList *rl, uint32_t begin, uint32_t end) {
    struct Range r;
    r.is_ipv6 = false;
    r.v4.begin = begin;
    r.v4.end = end;
    rangelist_push(rl, &r);
}

void rangelist_add_v6(struct RangeList *rl, const uint8_t begin[16], const uint8_t end[16]) {
    struct Range r;
    r.is_ipv6 = true;
    memcpy(r.v6.begin, begin, 16);
    memcpy(r.v6.end, end, 16);
    rangelist_push(rl, &r);
}

static uint32_t parse_ipv4(const char *str, bool *ok) {
    struct in_addr addr;
    if (inet_pton(AF_INET, str, &addr) == 1) {
        *ok = true;
        return ntohl(addr.s_addr);
    }
    *ok = false;
    return 0;
}

bool rangelist_add_string(struct RangeList *rl, const char *str) {
    while (*str && isspace((unsigned char)*str)) str++;
    if (!*str || *str == '#') return true;

    char buf[256];
    strncpy(buf, str, sizeof(buf) - 1);
    buf[sizeof(buf) - 1] = '\0';

    // Remove trailing whitespace/newlines
    size_t len = strlen(buf);
    while (len > 0 && (isspace((unsigned char)buf[len - 1]) || buf[len - 1] == '\r' || buf[len - 1] == '\n')) {
        buf[--len] = '\0';
    }

    // Check for CIDR block '/'
    char *slash = strchr(buf, '/');
    if (slash) {
        *slash = '\0';
        int cidr = atoi(slash + 1);

        // Check if IPv6 or IPv4
        if (strchr(buf, ':')) {
            struct in6_addr addr;
            if (inet_pton(AF_INET6, buf, &addr) == 1) {
                uint8_t begin[16], end[16];
                memcpy(begin, addr.s6_addr, 16);
                memcpy(end, addr.s6_addr, 16);

                if (cidr < 0) cidr = 0;
                if (cidr > 128) cidr = 128;

                for (int i = 0; i < 16; i++) {
                    int b = cidr - i * 8;
                    if (b <= 0) {
                        begin[i] &= 0x00;
                        end[i] |= 0xFF;
                    } else if (b < 8) {
                        uint8_t mask = (uint8_t)(0xFF << (8 - b));
                        begin[i] &= mask;
                        end[i] |= ~mask;
                    }
                }
                rangelist_add_v6(rl, begin, end);
                return true;
            }
        } else {
            bool ok;
            uint32_t ip = parse_ipv4(buf, &ok);
            if (ok) {
                if (cidr < 0) cidr = 0;
                if (cidr > 32) cidr = 32;
                uint32_t mask = (cidr == 0) ? 0 : (0xFFFFFFFFu << (32 - cidr));
                uint32_t begin = ip & mask;
                uint32_t end = begin | ~mask;
                rangelist_add(rl, begin, end);
                return true;
            }
        }
    }

    // Check for range '-'
    char *dash = strchr(buf, '-');
    if (dash && !strchr(buf, ':')) {
        *dash = '\0';
        bool ok1, ok2;
        uint32_t ip1 = parse_ipv4(buf, &ok1);
        uint32_t ip2 = parse_ipv4(dash + 1, &ok2);
        if (ok1 && ok2) {
            rangelist_add(rl, ip1, ip2);
            return true;
        }
    }

    // Single IP
    if (strchr(buf, ':')) {
        struct in6_addr addr;
        if (inet_pton(AF_INET6, buf, &addr) == 1) {
            rangelist_add_v6(rl, addr.s6_addr, addr.s6_addr);
            return true;
        }
    } else {
        bool ok;
        uint32_t ip = parse_ipv4(buf, &ok);
        if (ok) {
            rangelist_add(rl, ip, ip);
            return true;
        }
    }

    return false;
}

bool rangelist_add_file(struct RangeList *rl, const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) return false;

    char line[512];
    while (fgets(line, sizeof(line), fp)) {
        rangelist_add_string(rl, line);
    }

    fclose(fp);
    return true;
}

static int compare_ranges(const void *a, const void *b) {
    const struct Range *r1 = (const struct Range *)a;
    const struct Range *r2 = (const struct Range *)b;

    if (r1->is_ipv6 != r2->is_ipv6) {
        return r1->is_ipv6 ? 1 : -1;
    }

    if (!r1->is_ipv6) {
        if (r1->v4.begin < r2->v4.begin) return -1;
        if (r1->v4.begin > r2->v4.begin) return 1;
        if (r1->v4.end < r2->v4.end) return -1;
        if (r1->v4.end > r2->v4.end) return 1;
        return 0;
    } else {
        int c = memcmp(r1->v6.begin, r2->v6.begin, 16);
        if (c != 0) return c;
        return memcmp(r1->v6.end, r2->v6.end, 16);
    }
}

void rangelist_optimize(struct RangeList *targets, const struct RangeList *excludes) {
    if (targets->count == 0) return;

    // 1. Sort target ranges
    qsort(targets->list, targets->count, sizeof(struct Range), compare_ranges);

    // 2. Merge overlapping/adjacent targets
    struct RangeList merged;
    rangelist_init(&merged);

    for (size_t i = 0; i < targets->count; i++) {
        if (merged.count == 0) {
            rangelist_push(&merged, &targets->list[i]);
            continue;
        }

        struct Range *last = &merged.list[merged.count - 1];
        struct Range *curr = &targets->list[i];

        if (last->is_ipv6 == curr->is_ipv6) {
            if (!last->is_ipv6) {
                if (curr->v4.begin <= last->v4.end || curr->v4.begin == last->v4.end + 1) {
                    if (curr->v4.end > last->v4.end) {
                        last->v4.end = curr->v4.end;
                    }
                    continue;
                }
            } else {
                if (memcmp(curr->v6.begin, last->v6.end, 16) <= 0) {
                    if (memcmp(curr->v6.end, last->v6.end, 16) > 0) {
                        memcpy(last->v6.end, curr->v6.end, 16);
                    }
                    continue;
                }
            }
        }
        rangelist_push(&merged, curr);
    }

    // 3. Subtract excludes
    struct RangeList final_list;
    rangelist_init(&final_list);

    for (size_t i = 0; i < merged.count; i++) {
        struct Range cur = merged.list[i];
        if (cur.is_ipv6) {
            rangelist_push(&final_list, &cur);
            continue;
        }

        // Subtract IPv4 excludes
        struct RangeList work;
        rangelist_init(&work);
        rangelist_push(&work, &cur);

        for (size_t j = 0; j < excludes->count; j++) {
            if (excludes->list[j].is_ipv6) continue;

            uint32_t ex_b = excludes->list[j].v4.begin;
            uint32_t ex_e = excludes->list[j].v4.end;

            struct RangeList next_work;
            rangelist_init(&next_work);

            for (size_t k = 0; k < work.count; k++) {
                uint32_t w_b = work.list[k].v4.begin;
                uint32_t w_e = work.list[k].v4.end;

                if (ex_e < w_b || ex_b > w_e) {
                    // No overlap
                    rangelist_add(&next_work, w_b, w_e);
                } else if (ex_b <= w_b && ex_e >= w_e) {
                    // Entirely covered, remove
                } else if (ex_b > w_b && ex_e < w_e) {
                    // Split in middle
                    rangelist_add(&next_work, w_b, ex_b - 1);
                    rangelist_add(&next_work, ex_e + 1, w_e);
                } else if (ex_b <= w_b && ex_e < w_e) {
                    // Trim left
                    rangelist_add(&next_work, ex_e + 1, w_e);
                } else if (ex_b > w_b && ex_e >= w_e) {
                    // Trim right
                    rangelist_add(&next_work, w_b, ex_b - 1);
                }
            }

            rangelist_free(&work);
            work = next_work;
        }

        for (size_t k = 0; k < work.count; k++) {
            rangelist_push(&final_list, &work.list[k]);
        }
        rangelist_free(&work);
    }

    rangelist_free(&merged);
    free(targets->list);
    targets->list = final_list.list;
    targets->count = final_list.count;
    targets->max = final_list.max;
}
