        return r1->is_ipv6 ? 1 : -1;
    }

    if (!r1->is_ipv6) {
        if (r1->v4.begin < r2->v4.begin) return -1;
        if (r1->v4.begin > r2->v4.begin) return 1;
        if (r1->v4.end < r2->v4.end) return -1;
        if (r1->v4.end > r2->v4.end) return 1;
        return 0;
    } else {
        int c = memcmp(r1->v6.begin, r2->v6.begin, 16);
        if (c != 0) return c;
        return memcmp(r1->v6.end, r2->v6.end, 16);
    }
}

void rangelist_optimize(struct RangeList *targets, const struct RangeList *excludes) {
    if (targets->count == 0) return;

    // 1. Sort target ranges
    qsort(targets->list, targets->count, sizeof(struct Range), compare_ranges);

    // 2. Merge overlapping/adjacent targets
    struct RangeList merged;
    rangelist_init(&merged);

    for (size_t i = 0; i < targets->count; i++) {
        if (merged.count == 0) {
            rangelist_push(&merged, &targets->list[i]);
            continue;
        }

        struct Range *last = &merged.list[merged.count - 1];
        struct Range *curr = &targets->list[i];

        if (last->is_ipv6 == curr->is_ipv6) {
            if (!last->is_ipv6) {
                if (curr->v4.begin <= last->v4.end || curr->v4.begin == last->v4.end + 1) {
                    if (curr->v4.end > last->v4.end) {
                        last->v4.end = curr->v4.end;
                    }
                    continue;
                }
            } else {
                if (memcmp(curr->v6.begin, last->v6.end, 16) <= 0) {
                    if (memcmp(curr->v6.end, last->v6.end, 16) > 0) {
                        memcpy(last->v6.end, curr->v6.end, 16);
                    }
                    continue;
                }
            }
        }
        rangelist_push(&merged, curr);
    }

    // 3. Subtract excludes
    struct RangeList final_list;
    rangelist_init(&final_list);

    for (size_t i = 0; i < merged.count; i++) {
        struct Range cur = merged.list[i];
        if (cur.is_ipv6) {
            rangelist_push(&final_list, &cur);
            continue;
        }

        // Subtract IPv4 excludes
        struct RangeList work;
        rangelist_init(&work);
        rangelist_push(&work, &cur);

        for (size_t j = 0; j < excludes->count; j++) {
            if (excludes->list[j].is_ipv6) continue;

            uint32_t ex_b = excludes->list[j].v4.begin;
            uint32_t ex_e = excludes->list[j].v4.end;

            struct RangeList next_work;
            rangelist_init(&next_work);

            for (size_t k = 0; k < work.count; k++) {
                uint32_t w_b = work.list[k].v4.begin;
                uint32_t w_e = work.list[k].v4.end;

                if (ex_e < w_b || ex_b > w_e) {
                    // No overlap
                    rangelist_add(&next_work, w_b, w_e);
                } else if (ex_b <= w_b && ex_e >= w_e) {
                    // Entirely covered, remove
                } else if (ex_b > w_b && ex_e < w_e) {
                    // Split in middle
                    rangelist_add(&next_work, w_b, ex_b - 1);
                    rangelist_add(&next_work, ex_e + 1, w_e);
                } else if (ex_b <= w_b && ex_e < w_e) {
                    // Trim left
                    rangelist_add(&next_work, ex_e + 1, w_e);
                } else if (ex_b > w_b && ex_e >= w_e) {
                    // Trim right
                    rangelist_add(&next_work, w_b, ex_b - 1);
                }
            }

            rangelist_free(&work);
            work = next_work;
        }

        for (size_t k = 0; k < work.count; k++) {
            rangelist_push(&final_list, &work.list[k]);
        }
        rangelist_free(&work);
    }

    rangelist_free(&merged);
    free(targets->list);
    targets->list = final_list.list;
    targets->count = final_list.count;
    targets->max = final_list.max;
}
EOF
"}

