static uint64_t parse_size(const char *str) {
    char *end;
    double val = strtod(str, &end);
    while (*end && isspace((unsigned char)*end)) end++;
    if (*end == 'k' || *end == 'K') val *= 1024.0;
    else if (*end == 'm' || *end == 'M') val *= 1024.0 * 1024.0;
    else if (*end == 'g' || *end == 'G') val *= 1024.0 * 1024.0 * 1024.0;
    return (uint64_t)val;
}

void config_init(struct MasscanConfig *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->mode = MODE_SCAN;

    // Seed generation
    uint64_t s = (uint64_t)time(NULL);
    s ^= (uint64_t)(uintptr_t)cfg;
