bool config_parse_file(struct MasscanConfig *cfg, const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        char cwd[512] = {0};
        if (!getcwd(cwd, sizeof(cwd))) strncpy(cwd, "/workspace", sizeof(cwd)-1);
        fprintf(stderr, "[-] FAIL: reading configuration file\n");
        fprintf(stderr, "[-] %s: %s\n", filename, strerror(errno ? errno : ENOENT));
        fprintf(stderr, "[-] cwd = %s\n", cwd);
        return false;
    }

    char line[1024];
    while (fgets(line, sizeof(line), fp)) {
        char *p = line;
        while (*p && isspace((unsigned char)*p)) p++;
        if (!*p || *p == '#') continue;

        char *eq = strchr(p, '=');
        if (eq) {
            *eq = '\0';
            char *key = p;
            char *val = eq + 1;

            // Trim key
            char *end = key + strlen(key) - 1;
            while (end > key && isspace((unsigned char)*end)) *end-- = '\0';

            // Trim val
            while (*val && isspace((unsigned char)*val)) val++;
            end = val + strlen(val) - 1;
            while (end >= val && (isspace((unsigned char)*end) || *end == '\r' || *end == '\n')) *end-- = '\0';

            set_kv(cfg, key, val);
        }
    }

    fclose(fp);
    return true;
}

