void do_readscan(struct MasscanConfig *cfg) {
    fprintf(stderr, "[-] FAIL: failed to load libpcap shared library\n");
    fprintf(stderr, "    [hint]: you must install libpcap or WinPcap\n");

    if (cfg->readscan_file_count == 0) {
        fprintf(stderr, "[-] FAIL: --readscan\n");
        fprintf(stderr, "[-] (null): Bad address\n");
        return;
    }

    for (int i = 0; i < cfg->readscan_file_count; i++) {
        const char *filename = cfg->readscan_files[i];
        FILE *fp = fopen(filename, "rb");
        if (!fp) {
            fprintf(stderr, "[-] FAIL: --readscan\n");
            fprintf(stderr, "[-] %s: %s\n", filename, strerror(errno ? errno : ENOENT));
        } else {
            fprintf(stderr, "[+] --readscan %s\n", filename);
            fprintf(stderr, "[-] %s: Success\n", filename);
            fclose(fp);
        }
    }

    if (cfg->output_filename[0]) {
        FILE *out_fp = fopen(cfg->output_filename, "w");
        if (out_fp) fclose(out_fp);
    }
}
EOF
"}

