#define _POSIX_C_SOURCE 200809L
#include "config.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>

static uint64_t parse_size(const char *str) {
    char *end;
    double val = strtod(str, &end);
    while (*end && isspace((unsigned char)*end)) end++;
    if (*end == 'k' || *end == 'K') val *= 1024.0;
    else if (*end == 'm' || *end == 'M') val *= 1024.0 * 1024.0;
    else if (*end == 'g' || *end == 'G') val *= 1024.0 * 1024.0 * 1024.0;
    return (uint64_t)val;
}

void config_init(struct MasscanConfig *cfg) {
    memset(cfg, 0, sizeof(*cfg));
    cfg->mode = MODE_SCAN;

    // Seed generation
    uint64_t s = (uint64_t)time(NULL);
    s ^= (uint64_t)(uintptr_t)cfg;
    s = s * 6364136223846793005ULL + 1442695040888963407ULL;
    cfg->seed = s;
    cfg->seed_set = false;

    cfg->rate = 100.0;
    cfg->shard_index = 1;
    cfg->shard_total = 1;

    cfg->connection_timeout = 30;
    cfg->wait = 10;

    rangelist_init(&cfg->targets);
    rangelist_init(&cfg->excludes);
    portlist_init(&cfg->ports);
}

void config_free(struct MasscanConfig *cfg) {
    rangelist_free(&cfg->targets);
    rangelist_free(&cfg->excludes);
    portlist_free(&cfg->ports);
}

static bool set_kv(struct MasscanConfig *cfg, const char *key, const char *val) {
    if (!key || !*key) return false;

    if (strcmp(key, "rate") == 0 || strcmp(key, "max-rate") == 0) {
        cfg->rate = strtod(val ? val : "100", NULL);
    } else if (strcmp(key, "ports") == 0 || strcmp(key, "port") == 0) {
        portlist_add_string(&cfg->ports, val);
    } else if (strcmp(key, "range") == 0 || strcmp(key, "target") == 0) {
        rangelist_add_string(&cfg->targets, val);
    } else if (strcmp(key, "exclude") == 0) {
        rangelist_add_string(&cfg->excludes, val);
    } else if (strcmp(key, "excludefile") == 0) {
        rangelist_add_file(&cfg->excludes, val);
    } else if (strcmp(key, "include-file") == 0 || strcmp(key, "includefile") == 0) {
        rangelist_add_file(&cfg->targets, val);
    } else if (strcmp(key, "banners") == 0 || strcmp(key, "banner") == 0) {
        if (!val || strcmp(val, "true") == 0 || strcmp(val, "1") == 0) cfg->banners = true;
        else cfg->banners = false;
    } else if (strcmp(key, "offline") == 0) {
        if (!val || strcmp(val, "true") == 0 || strcmp(val, "1") == 0) cfg->offline = true;
        else cfg->offline = false;
    } else if (strcmp(key, "seed") == 0) {
        if (val) {
            cfg->seed = strtoull(val, NULL, 0);
            cfg->seed_set = true;
        }
    } else if (strcmp(key, "shard") == 0) {
        if (val) {
            sscanf(val, "%u/%u", &cfg->shard_index, &cfg->shard_total);
        }
    } else if (strcmp(key, "retries") == 0) {
        if (val) cfg->retries = (uint32_t)atoi(val);
    } else if (strcmp(key, "ttl") == 0 || strcmp(key, "ip-ttl") == 0) {
        if (val) cfg->ttl = (uint32_t)atoi(val);
    } else if (strcmp(key, "wait") == 0) {
        if (val) cfg->wait = (uint32_t)atoi(val);
    } else if (strcmp(key, "connection-timeout") == 0) {
        if (val) cfg->connection_timeout = (uint32_t)atoi(val);
    } else if (strcmp(key, "min-packet") == 0) {
        if (val) cfg->min_packet = (uint32_t)atoi(val);
    } else if (strcmp(key, "adapter") == 0) {
        if (val) strncpy(cfg->adapter, val, sizeof(cfg->adapter) - 1);
    } else if (strcmp(key, "adapter-ip") == 0 || strcmp(key, "source-ip") == 0) {
        if (val) strncpy(cfg->adapter_ip, val, sizeof(cfg->adapter_ip) - 1);
    } else if (strcmp(key, "adapter-mac") == 0 || strcmp(key, "source-mac") == 0) {
        if (val) strncpy(cfg->adapter_mac, val, sizeof(cfg->adapter_mac) - 1);
    } else if (strcmp(key, "adapter-port") == 0 || strcmp(key, "source-port") == 0) {
        if (val) cfg->adapter_port = (uint32_t)atoi(val);
    } else if (strcmp(key, "router-ip") == 0) {
        if (val) strncpy(cfg->router_ip, val, sizeof(cfg->router_ip) - 1);
    } else if (strcmp(key, "router-mac") == 0) {
        if (val) {
            strncpy(cfg->router_mac_ipv4, val, sizeof(cfg->router_mac_ipv4) - 1);
            strncpy(cfg->router_mac_ipv6, val, sizeof(cfg->router_mac_ipv6) - 1);
        }
    } else if (strcmp(key, "router-mac-ipv4") == 0) {
        if (val) strncpy(cfg->router_mac_ipv4, val, sizeof(cfg->router_mac_ipv4) - 1);
    } else if (strcmp(key, "router-mac-ipv6") == 0) {
        if (val) strncpy(cfg->router_mac_ipv6, val, sizeof(cfg->router_mac_ipv6) - 1);
    } else if (strcmp(key, "output-filename") == 0) {
        if (val) strncpy(cfg->output_filename, val, sizeof(cfg->output_filename) - 1);
    } else if (strcmp(key, "output-format") == 0) {
        if (val) strncpy(cfg->output_format, val, sizeof(cfg->output_format) - 1);
    } else if (strcmp(key, "rotate") == 0) {
        if (val) cfg->rotate = (uint32_t)atoi(val);
    } else if (strcmp(key, "rotate-dir") == 0) {
        if (val) strncpy(cfg->rotate_dir, val, sizeof(cfg->rotate_dir) - 1);
    } else if (strcmp(key, "rotate-offset") == 0) {
        if (val) cfg->rotate_offset = (uint32_t)atoi(val);
    } else if (strcmp(key, "rotate-size") == 0) {
        if (val) cfg->rotate_size = parse_size(val);
    } else if (strcmp(key, "pcap-payloads") == 0) {
        if (val) strncpy(cfg->pcap_payloads, val, sizeof(cfg->pcap_payloads) - 1);
    } else if (strcmp(key, "nmap-payloads") == 0) {
        if (val) strncpy(cfg->nmap_payloads, val, sizeof(cfg->nmap_payloads) - 1);
    } else if (strcmp(key, "http-user-agent") == 0) {
        if (val) strncpy(cfg->http_user_agent, val, sizeof(cfg->http_user_agent) - 1);
    } else if (strcmp(key, "http-payload") == 0) {
        if (val) strncpy(cfg->http_payload, val, sizeof(cfg->http_payload) - 1);
    } else if (strcmp(key, "http-host") == 0) {
        if (val) strncpy(cfg->http_host, val, sizeof(cfg->http_host) - 1);
    } else if (strcmp(key, "http-url") == 0) {
        if (val) strncpy(cfg->http_url, val, sizeof(cfg->http_url) - 1);
    } else if (strcmp(key, "hello") == 0) {
        if (val) strncpy(cfg->hello, val, sizeof(cfg->hello) - 1);
    }
    return true;
}

bool config_parse_file(struct MasscanConfig *cfg, const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        char cwd[512] = {0};
        if (!getcwd(cwd, sizeof(cwd))) strncpy(cwd, "/workspace", sizeof(cwd)-1);
        fprintf(stderr, "[-] FAIL: reading configuration file\n");
        fprintf(stderr, "[-] %s: %s\n", filename, strerror(errno ? errno : ENOENT));
        fprintf(stderr, "[-] cwd = %s\n", cwd);
        return false;
    }

    char line[1024];
    while (fgets(line, sizeof(line), fp)) {
        char *p = line;
        while (*p && isspace((unsigned char)*p)) p++;
        if (!*p || *p == '#') continue;

        char *eq = strchr(p, '=');
        if (eq) {
            *eq = '\0';
            char *key = p;
            char *val = eq + 1;

            // Trim key
            char *end = key + strlen(key) - 1;
            while (end > key && isspace((unsigned char)*end)) *end-- = '\0';

            // Trim val
            while (*val && isspace((unsigned char)*val)) val++;
            end = val + strlen(val) - 1;
            while (end >= val && (isspace((unsigned char)*end) || *end == '\r' || *end == '\n')) *end-- = '\0';

            set_kv(cfg, key, val);
        }
    }

    fclose(fp);
    return true;
}

bool config_parse_args(struct MasscanConfig *cfg, int argc, char **argv) {
    for (int i = 1; i < argc; i++) {
        const char *arg = argv[i];

        if (strcmp(arg, "--version") == 0 || strcmp(arg, "-V") == 0) {
            cfg->mode = MODE_VERSION;
            return true;
        }
        if (strcmp(arg, "-h") == 0 || strcmp(arg, "-?") == 0) {
            cfg->mode = MODE_HELP_SHORT;
            return true;
