bool config_parse_file(struct MasscanConfig *cfg, const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        char cwd[512] = {0};
        if (!getcwd(cwd, sizeof(cwd))) strncpy(cwd, "/workspace", sizeof(cwd)-1);
        fprintf(stderr, "[-] FAIL: reading configuration file\n");
        fprintf(stderr, "[-] %s: %s\n", filename, strerror(errno ? errno : ENOENT));
        fprintf(stderr, "[-] cwd = %s\n", cwd);
        return false;
    }

    char line[1024];
    while (fgets(line, sizeof(line), fp)) {
        char *p = line;
        while (*p && isspace((unsigned char)*p)) p++;
        if (!*p || *p == '#') continue;

        char *eq = strchr(p, '=');
        if (eq) {
            *eq = '\0';
            char *key = p;
            char *val = eq + 1;

            // Trim key
            char *end = key + strlen(key) - 1;
            while (end > key && isspace((unsigned char)*end)) *end-- = '\0';

            // Trim val
            while (*val && isspace((unsigned char)*val)) val++;
            end = val + strlen(val) - 1;
            while (end >= val && (isspace((unsigned char)*end) || *end == '\r' || *end == '\n')) *end-- = '\0';

            set_kv(cfg, key, val);
        }
    }

    fclose(fp);
    return true;
}

bool config_parse_args(struct MasscanConfig *cfg, int argc, char **argv) {
    for (int i = 1; i < argc; i++) {
        const char *arg = argv[i];

        if (strcmp(arg, "--version") == 0 || strcmp(arg, "-V") == 0) {
            cfg->mode = MODE_VERSION;
            return true;
        }
        if (strcmp(arg, "-h") == 0 || strcmp(arg, "-?") == 0) {
            cfg->mode = MODE_HELP_SHORT;
            return true;
        }
        if (strcmp(arg, "--help") == 0) {
            cfg->mode = MODE_HELP_LONG;
            return true;
        }
        if (strcmp(arg, "--nmap") == 0) {
            cfg->mode = MODE_NMAP;
            return true;
        }
        if (strcmp(arg, "--selftest") == 0 || strcmp(arg, "--regress") == 0) {
            cfg->mode = MODE_SELFTEST;
            return true;
        }
        if (strcmp(arg, "--iflist") == 0) {
            cfg->mode = MODE_IFLIST;
            return true;
        }
        if (strcmp(arg, "--echo") == 0) {
            cfg->mode = MODE_ECHO;
            continue;
        }
        if (strcmp(arg, "--readscan") == 0) {
            cfg->mode = MODE_READSCAN;
            cfg->readscan_set = true;
            // Collect any subsequent filenames until next option
            while (i + 1 < argc && argv[i + 1][0] != '-') {
                if (cfg->readscan_file_count < 16) {
                    strncpy(cfg->readscan_files[cfg->readscan_file_count++], argv[i + 1], 511);
                }
                i++;
            }
            continue;
        }

        // Check unsupported / special nmap flags
        if (strcmp(arg, "-sT") == 0) {
            fprintf(stderr, "nmap(-sT): connect() is too synchronous for cool kids\nWARNING: doing SYN scan (-sS) anyway, ignoring (-sT)\n");
            continue;
        }
        if (strcmp(arg, "-sA") == 0) {
            cfg->mode = MODE_UNSUPPORTED_NMAP;
            snprintf(cfg->unsupported_nmap_msg, sizeof(cfg->unsupported_nmap_msg), "nmap(-sA): ACK scan not yet supported\n");
            return true;
        }
        if (strcmp(arg, "-sN") == 0) {
            cfg->mode = MODE_UNSUPPORTED_NMAP;
            snprintf(cfg->unsupported_nmap_msg, sizeof(cfg->unsupported_nmap_msg), "nmap(-sN): NULL scan not yet supported\n");
            return true;
        }
        if (strcmp(arg, "-sF") == 0) {
            cfg->mode = MODE_UNSUPPORTED_NMAP;
            snprintf(cfg->unsupported_nmap_msg, sizeof(cfg->unsupported_nmap_msg), "nmap(-sF): FIN scan not yet supported\n");
            return true;
        }
        if (strcmp(arg, "-sX") == 0) {
            cfg->mode = MODE_UNSUPPORTED_NMAP;
            snprintf(cfg->unsupported_nmap_msg, sizeof(cfg->unsupported_nmap_msg), "nmap(-sX): Xmas scan not yet supported\n");
            return true;
        }
        if (strcmp(arg, "-sP") == 0) {
            cfg->mode = MODE_UNSUPPORTED_NMAP;
            snprintf(cfg->unsupported_nmap_msg, sizeof(cfg->unsupported_nmap_msg), "nmap(-sP): unsupported option\n");
            return true;
        }
        if (strcmp(arg, "-sL") == 0) {
            cfg->mode = MODE_LIST_SCAN;
            continue;
        }
        if (strcmp(arg, "-sW") == 0) {
            cfg->mode = MODE_UNSUPPORTED_NMAP;
            snprintf(cfg->unsupported_nmap_msg, sizeof(cfg->unsupported_nmap_msg), "nmap(-sW): Windows scan not yet supported\n");
            return true;
        }
        if (strcmp(arg, "-sM") == 0) {
            cfg->mode = MODE_UNSUPPORTED_NMAP;
            snprintf(cfg->unsupported_nmap_msg, sizeof(cfg->unsupported_nmap_msg), "nmap(-sM): Maimon scan not yet supported\n");
            return true;
        }
        if (strcmp(arg, "-O") == 0) {
            cfg->mode = MODE_UNSUPPORTED_NMAP;
            snprintf(cfg->unsupported_nmap_msg, sizeof(cfg->unsupported_nmap_msg), "nmap(-O): unsupported, OS detection is too complex\n");
            return true;
        }
        if (strcmp(arg, "-sV") == 0) {
            cfg->mode = MODE_UNSUPPORTED_NMAP;
            snprintf(cfg->unsupported_nmap_msg, sizeof(cfg->unsupported_nmap_msg), "nmap(-sV): unlikely this will be supported\n");
            return true;
        }
        if (strcmp(arg, "-A") == 0) {
            cfg->mode = MODE_UNSUPPORTED_NMAP;
            snprintf(cfg->unsupported_nmap_msg, sizeof(cfg->unsupported_nmap_msg), "nmap(-A): unsupported: this tool only does SYN scan\n");
            return true;
        }
        if (strcmp(arg, "-P0") == 0) {
            cfg->mode = MODE_UNSUPPORTED_NMAP;
            snprintf(cfg->unsupported_nmap_msg, sizeof(cfg->unsupported_nmap_msg), "nmap(-P0): unsupported option, maybe in future\n");
            return true;
        }
        if (strcmp(arg, "-F") == 0) {
