        if (strcmp(arg, "-oB") == 0) {
            strncpy(cfg->output_format, "binary", sizeof(cfg->output_format) - 1);
            if (i + 1 < argc) strncpy(cfg->output_filename, argv[++i], sizeof(cfg->output_filename) - 1);
            continue;
        }
        if (strcmp(arg, "-oU") == 0) {
            strncpy(cfg->output_format, "unicornscan", sizeof(cfg->output_format) - 1);
            if (i + 1 < argc) strncpy(cfg->output_filename, argv[++i], sizeof(cfg->output_filename) - 1);
            continue;
        }

        if (strcmp(arg, "--output-format") == 0) {
            if (i + 1 < argc) strncpy(cfg->output_format, argv[++i], sizeof(cfg->output_format) - 1);
            continue;
        }
        if (strcmp(arg, "--output-filename") == 0) {
            if (i + 1 < argc) strncpy(cfg->output_filename, argv[++i], sizeof(cfg->output_filename) - 1);
            continue;
        }

        if (strcmp(arg, "--rotate") == 0) {
            if (i + 1 < argc) cfg->rotate = (uint32_t)atoi(argv[++i]);
            continue;
        }
        if (strcmp(arg, "--rotate-dir") == 0) {
            if (i + 1 < argc) strncpy(cfg->rotate_dir, argv[++i], sizeof(cfg->rotate_dir) - 1);
            continue;
        }
        if (strcmp(arg, "--rotate-offset") == 0) {
            if (i + 1 < argc) cfg->rotate_offset = (uint32_t)atoi(argv[++i]);
            continue;
        }
        if (strcmp(arg, "--rotate-size") == 0) {
            if (i + 1 < argc) cfg->rotate_size = parse_size(argv[++i]);
            continue;
        }

        if (strcmp(arg, "--pcap-payloads") == 0) {
            if (i + 1 < argc) strncpy(cfg->pcap_payloads, argv[++i], sizeof(cfg->pcap_payloads) - 1);
            continue;
        }
        if (strcmp(arg, "--nmap-payloads") == 0) {
            if (i + 1 < argc) strncpy(cfg->nmap_payloads, argv[++i], sizeof(cfg->nmap_payloads) - 1);
            continue;
        }
        if (strcmp(arg, "--http-user-agent") == 0) {
            if (i + 1 < argc) strncpy(cfg->http_user_agent, argv[++i], sizeof(cfg->http_user_agent) - 1);
            continue;
        }
        if (strcmp(arg, "--http-payload") == 0) {
            if (i + 1 < argc) strncpy(cfg->http_payload, argv[++i], sizeof(cfg->http_payload) - 1);
            continue;
        }
        if (strcmp(arg, "--http-host") == 0) {
            if (i + 1 < argc) strncpy(cfg->http_host, argv[++i], sizeof(cfg->http_host) - 1);
            continue;
        }
        if (strcmp(arg, "--http-url") == 0) {
            if (i + 1 < argc) strncpy(cfg->http_url, argv[++i], sizeof(cfg->http_url) - 1);
            continue;
        }
        if (strcmp(arg, "--hello") == 0) {
            if (i + 1 < argc) strncpy(cfg->hello, argv[++i], sizeof(cfg->hello) - 1);
            continue;
        }

        // Ignored options
        if (strcmp(arg, "-sS") == 0 || strcmp(arg, "-Pn") == 0 || strcmp(arg, "-n") == 0) {
            continue;
        }

        // Positional argument -> IP range target
        if (arg[0] != '-') {
            rangelist_add_string(&cfg->targets, arg);
            continue;
        }
    }

    return true;
}
EOF
"}

{"command":"cat <<'EOF' > src/ports.c
#define _POSIX_C_SOURCE 200809L
#include "ports.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

void portlist_init(struct PortList *pl) {
    pl->list = NULL;
    pl->count = 0;
    pl->max = 0;
}

void portlist_free(struct PortList *pl) {
    if (pl->list) {
        free(pl->list);
        pl->list = NULL;
    }
    pl->count = 0;
    pl->max = 0;
}

void portlist_add(struct PortList *pl, uint16_t begin, uint16_t end, int proto) {
    if (pl->count >= pl->max) {
        pl->max = pl->max ? pl->max * 2 : 16;
        pl->list = realloc(pl->list, pl->max * sizeof(struct PortRange));
    }
    pl->list[pl->count].begin = begin;
    pl->list[pl->count].end = end;
    pl->list[pl->count].proto = proto;
    pl->count++;
}

bool portlist_add_string(struct PortList *pl, const char *str) {
    if (!str || !*str) return false;

    int current_proto = PROTO_TCP;

    char *buf = strdup(str);
    char *token = strtok(buf, ",");

    while (token) {
        while (*token && isspace((unsigned char)*token)) token++;

        if (*token) {
            // Check for prefix
            if (token[0] && token[1] == ':') {
                char p = toupper((unsigned char)token[0]);
                if (p == 'T') current_proto = PROTO_TCP;
                else if (p == 'U') current_proto = PROTO_UDP;
                else if (p == 'S') current_proto = PROTO_SCTP;
                else if (p == 'I') current_proto = PROTO_ICMP;
                else if (p == 'O') current_proto = PROTO_ICMP; // IP protocol
                token += 2;
            }

            // Check range
            char *dash = strchr(token, '-');
            if (dash) {
                *dash = '\0';
                int b = atoi(token);
                int e = atoi(dash + 1);
                if (b >= 0 && e >= b) {
                    portlist_add(pl, (uint16_t)b, (uint16_t)e, current_proto);
                }
            } else {
                int p = atoi(token);
                if (token[0] && (token[0] == 'O' || token[0] == 'o') && token[1] == ':') {
                    // Handled above
                } else if (p >= 0) {
                    if (p < 256 && (token - 2 >= buf && (token[-2] == 'O' || token[-2] == 'o'))) {
                        p += 256;
                    }
                    portlist_add(pl, (uint16_t)p, (uint16_t)p, current_proto);
                }
            }
        }
        token = strtok(NULL, ",");
    }

    free(buf);
    return true;
}

size_t portlist_count(const struct PortList *pl) {
    size_t total = 0;
    for (size_t i = 0; i < pl->count; i++) {
        total += (pl->list[i].end - pl->list[i].begin + 1);
    }
    return total;
}

static int compare_ports(const void *a, const void *b) {
    const struct PortRange *p1 = (const struct PortRange *)a;
    const struct PortRange *p2 = (const struct PortRange *)b;

    if (p1->proto != p2->proto) return p1->proto - p2->proto;
    if (p1->begin != p2->begin) return (int)p1->begin - (int)p2->begin;
    return (int)p1->end - (int)p2->end;
}

void portlist_optimize(struct PortList *pl) {
    if (pl->count <= 1) return;

    qsort(pl->list, pl->count, sizeof(struct PortRange), compare_ports);

    struct PortList merged;
    portlist_init(&merged);

    for (size_t i = 0; i < pl->count; i++) {
        if (merged.count == 0) {
            portlist_add(&merged, pl->list[i].begin, pl->list[i].end, pl->list[i].proto);
            continue;
        }

        struct PortRange *last = &merged.list[merged.count - 1];
        struct PortRange *curr = &pl->list[i];

        if (last->proto == curr->proto && curr->begin <= last->end + 1) {
            if (curr->end > last->end) {
                last->end = curr->end;
            }
        } else {
            portlist_add(&merged, curr->begin, curr->end, curr->proto);
        }
    }

    free(pl->list);
    pl->list = merged.list;
    pl->count = merged.count;
    pl->max = merged.max;
}
EOF
"}

