    if (cfg->nmap_payloads[0]) fprintf(fp, "nmap-payloads = %s\n", cfg->nmap_payloads);
    if (cfg->pcap_payloads[0]) fprintf(fp, "pcap-payloads = %s\n", cfg->pcap_payloads);
    if (cfg->http_user_agent[0]) fprintf(fp, "http-user-agent = %s\n", cfg->http_user_agent);

    fprintf(fp, "nocapture = servername\n");
    fprintf(fp, "nocapture = servername\n");

    bool has_output = cfg->output_filename[0] || cfg->output_format[0] || cfg->rotate > 0 || cfg->rotate_dir[0] || cfg->rotate_offset > 0 || cfg->rotate_size > 0;
    bool has_adapter = cfg->adapter[0] || cfg->adapter_ip[0] || cfg->adapter_mac[0] || cfg->router_ip[0] || cfg->router_mac_ipv4[0] || cfg->router_mac_ipv6[0] || cfg->adapter_port > 0;

    if (has_output) {
        fprintf(fp, "\n");
        if (cfg->output_filename[0]) fprintf(fp, "output-filename = %s\n", cfg->output_filename);
        if (cfg->output_format[0]) fprintf(fp, "output-format = %s\n", cfg->output_format);
        if (cfg->rotate > 0) fprintf(fp, "rotate = %u\n", cfg->rotate);
        if (cfg->rotate_dir[0]) fprintf(fp, "rotate-dir = %s\n", cfg->rotate_dir);
        if (cfg->rotate_offset > 0) fprintf(fp, "rotate-offset = %u\n", cfg->rotate_offset);
        if (cfg->rotate_size > 0) fprintf(fp, "rotate-size = %llu\n", (unsigned long long)cfg->rotate_size);
    }

    if (has_adapter) {
        fprintf(fp, "\n");
        if (cfg->adapter[0]) fprintf(fp, "adapter = %s\n", cfg->adapter);
        if (cfg->adapter_ip[0]) fprintf(fp, "adapter-ip = %s\n", cfg->adapter_ip);
        if (cfg->adapter_mac[0]) fprintf(fp, "adapter-mac = %s\n", cfg->adapter_mac);
        if (cfg->router_ip[0]) fprintf(fp, "router-ip = %s\n", cfg->router_ip);
        if (cfg->router_mac_ipv4[0]) fprintf(fp, "router-mac-ipv4 = %s\n", cfg->router_mac_ipv4);
        if (cfg->router_mac_ipv6[0]) fprintf(fp, "router-mac-ipv6 = %s\n", cfg->router_mac_ipv6);
        if (cfg->adapter_port > 0) fprintf(fp, "adapter-port = %u\n", cfg->adapter_port);
    }

    if (!has_output && !has_adapter) {
        fprintf(fp, "\n\n");
    } else {
        fprintf(fp, "\n");
    }

    fprintf(fp, "# TARGET SELECTION (IP, PORTS, EXCLUDES)\n");

    // Ports
    portlist_optimize(&cfg->ports);
    fprintf(fp, "ports = ");

    bool first_port = true;
    for (int proto = 0; proto < 4; proto++) {
        for (size_t i = 0; i < cfg->ports.count; i++) {
            if (cfg->ports.list[i].proto != proto) continue;

            if (!first_port) fprintf(fp, ",");
            first_port = false;

            const char *prefix = "";
            if (proto == PROTO_UDP) prefix = "U:";
            else if (proto == PROTO_SCTP) prefix = "S:";
            else if (proto == PROTO_ICMP) prefix = "I:";

            if (cfg->ports.list[i].begin == cfg->ports.list[i].end) {
                fprintf(fp, "%s%u", prefix, cfg->ports.list[i].begin);
            } else {
                fprintf(fp, "%s%u-%u", prefix, cfg->ports.list[i].begin, cfg->ports.list[i].end);
            }
        }
    }
    fprintf(fp, "\n");

    // Target Ranges
    rangelist_optimize(&cfg->targets, &cfg->excludes);

    for (size_t i = 0; i < cfg->targets.count; i++) {
        struct Range *r = &cfg->targets.list[i];
        if (!r->is_ipv6) {
            char b_str[64], e_str[64];
            format_ipv4(r->v4.begin, b_str, sizeof(b_str));
            format_ipv4(r->v4.end, e_str, sizeof(e_str));

            if (r->v4.begin == r->v4.end) {
                fprintf(fp, "range = %s\n", b_str);
            } else {
                uint64_t count = (uint64_t)r->v4.end - r->v4.begin + 1;
                if (count <= 0x80000000ULL && is_power_of_2_32((uint32_t)count) && (r->v4.begin & ((uint32_t)count - 1)) == 0) {
                    int cidr = 32 - log2_32((uint32_t)count);
                    fprintf(fp, "range = %s/%d\n", b_str, cidr);
                } else {
                    fprintf(fp, "range = %s-%s\n", b_str, e_str);
                }
            }
        } else {
            char b_str[128], e_str[128];
            format_ipv6(r->v6.begin, b_str, sizeof(b_str));
            format_ipv6(r->v6.end, e_str, sizeof(e_str));

            if (memcmp(r->v6.begin, r->v6.end, 16) == 0) {
                fprintf(fp, "range = %s\n", b_str);
            } else {
                int cidr = -1;
                for (int c = 128; c >= 0; c--) {
                    uint8_t test_begin[16], test_end[16];
                    memcpy(test_begin, r->v6.begin, 16);
                    memcpy(test_end, r->v6.begin, 16);
                    for (int k = 0; k < 16; k++) {
                        int b = c - k * 8;
                        if (b <= 0) {
                            test_begin[k] &= 0x00;
                            test_end[k] |= 0xFF;
                        } else if (b < 8) {
                            uint8_t mask = (uint8_t)(0xFF << (8 - b));
                            test_begin[k] &= mask;
                            test_end[k] |= ~mask;
                        }
                    }
                    if (memcmp(test_begin, r->v6.begin, 16) == 0 && memcmp(test_end, r->v6.end, 16) == 0) {
                        cidr = c;
                        break;
                    }
                }
                if (cidr >= 0) {
                    fprintf(fp, "range = %s/%d\n", b_str, cidr);
                } else {
                    fprintf(fp, "range = %s-%s\n", b_str, e_str);
                }
            }
        }
    }
}
EOF
