#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "config.h"
#include "echo.h"
#include "readscan.h"

static void print_short_help(void) {
    printf("usage: masscan [options] [<IP|RANGE>... -pPORT[,PORT...]]\n\n");
